import app from './worker-v134.js';
import { MARKET_SCHEMA_V135 } from './market-schema-v135.js';

const HEADERS={'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'};
const LISTING_STATUSES=new Set(['DRAFT','ACTIVE','RESERVED','TRANSFER_PENDING','SOLD','WITHDRAWN','EXPIRED']);
const CONDITION_GRADES=new Set(['NEW_OTHER','EXCELLENT','GOOD','FAIR','POOR','FOR_PARTS']);
const CONDITION_RANK={FOR_PARTS:0,POOR:1,FAIR:2,GOOD:3,EXCELLENT:4,NEW_OTHER:5};
const WANTED_STATUSES=new Set(['ACTIVE','PAUSED','FULFILLED','EXPIRED']);
const ALLOWED_CATEGORIES=new Set(['electronics','appliances','tools','furniture','sports','photography','audio','musical_instruments','books','collectibles','clothing','home','garden']);
const OFFER_STATUSES=new Set(['PENDING','ACCEPTED','COUNTERED','DECLINED','WITHDRAWN','EXPIRED']);
const DEAL_STATUSES=new Set(['AGREED','PAYMENT_PENDING','READY_FOR_HANDOFF','TRANSFER_PENDING','COMPLETED','CANCELLED','DISPUTED']);
const DELIVERY_MODES=new Set(['PICKUP','SHIPPING_EXTERNAL']);
const now=()=>new Date().toISOString();
const uid=prefix=>`${prefix}${crypto.randomUUID().replaceAll('-','')}`;
const publicId=prefix=>`${prefix}-${crypto.randomUUID().replaceAll('-','').slice(0,16).toUpperCase()}`;
const clean=(value,max=5000)=>String(value??'').replace(/\0/g,'').trim().slice(0,max);
const normalized=value=>clean(value,5000).toLocaleLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();
const safeJson=(value,fallback={})=>{try{return JSON.parse(value||'')}catch{return fallback}};
const json=(value,status=200,headers={})=>new Response(JSON.stringify(value),{status,headers:{...HEADERS,...headers}});
const cents=value=>{if(value===null||value===undefined||value==='')return null;const n=Number(value);return Number.isInteger(n)&&n>=0&&n<=1_000_000_000?n:null};
const currency=value=>/^[A-Z]{3}$/.test(clean(value,3).toUpperCase())?clean(value,3).toUpperCase():'EUR';
const safeDate=value=>{const x=clean(value,10);if(!x)return null;if(!/^\d{4}-\d{2}-\d{2}$/.test(x))return null;const d=new Date(`${x}T00:00:00Z`);return Number.isNaN(d.valueOf())||d.toISOString().slice(0,10)!==x?null:x};
const bool=value=>value===true||value===1||value==='1';
const list=value=>[...new Set((Array.isArray(value)?value:String(value||'').split(',')).map(x=>clean(x,120)).filter(Boolean))].slice(0,30);
const category=value=>{const key=normalized(value).replaceAll(' ','_');return ALLOWED_CATEGORIES.has(key)?key:null};
function log(event,fields={}){console.log(JSON.stringify({scope:'still_market',event,at:now(),...fields}))}
async function sha(value){const d=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(value)));return[...new Uint8Array(d)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function cookie(request,name){for(const part of(request.headers.get('cookie')||'').split(';')){const[k,...v]=part.trim().split('=');if(k===name)return decodeURIComponent(v.join('='))}return''}
async function buyerSession(request,env){const token=cookie(request,'still_buyer');if(!token||!env.DB)return null;return env.DB.prepare(`SELECT a.id buyer_account_id,a.email,a.name,a.email_verified,a.created_at account_created_at FROM buyer_sessions s JOIN buyer_accounts a ON a.id=s.buyer_account_id WHERE s.token_hash=? AND s.expires_at>? AND a.status='active'`).bind(await sha(token),now()).first()}
function sameOrigin(request){const origin=request.headers.get('origin');return!origin||origin===new URL(request.url).origin}
function rewrite(request,pathname){const url=new URL(request.url);url.pathname=pathname;url.search='';return new Request(url,{method:'GET',headers:request.headers})}
let schemaReady;
async function ensureSchema(env){if(!schemaReady)schemaReady=env.DB.batch(MARKET_SCHEMA_V135.map(sql=>env.DB.prepare(sql))).catch(error=>{schemaReady=undefined;throw error});await schemaReady}
function historyStatement(env,buyerId,type,id,event,title,details={},sourceType='market',sourceId=null){const ts=now();return env.DB.prepare(`INSERT INTO world_history_events(id,public_id,buyer_account_id,entity_type,entity_public_id,event_type,title,details_json,source_type,source_public_id,occurred_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)`).bind(uid('whe_'),publicId('HIS'),buyerId,type,id,event,title,JSON.stringify(details).slice(0,4000),sourceType,sourceId,ts,ts)}
function notificationStatement(env,buyerId,sourceKey,type,title,body,href){return env.DB.prepare(`INSERT OR IGNORE INTO market_notifications(id,public_id,buyer_account_id,source_key,notification_type,title,body,href,created_at) VALUES(?,?,?,?,?,?,?,?,?)`).bind(uid('mno_'),publicId('NTF'),buyerId,sourceKey,type,clean(title,180),clean(body,500)||null,clean(href,500),now())}

const THING_SELECT=`SELECT p.*,tp.thing_type,tp.category,tp.manufacturer,tp.model,tp.serial_number,tp.gtin,tp.purchase_price_cents,tp.currency,tp.lifecycle_state,tp.source,tp.review_status FROM ownership_passports p LEFT JOIN world_thing_profiles tp ON tp.passport_id=p.id`;
async function ownerThing(env,buyerId,id){return env.DB.prepare(`${THING_SELECT} WHERE p.buyer_account_id=? AND p.public_id=? AND p.status<>'archived'`).bind(buyerId,id).first()}
async function thingByInternal(env,id){return env.DB.prepare(`${THING_SELECT} WHERE p.id=?`).bind(id).first()}
async function blockExists(env,a,b){if(!a||!b)return false;const row=await env.DB.prepare(`SELECT 1 ok FROM market_blocks WHERE (blocker_buyer_account_id=? AND blocked_buyer_account_id=?) OR (blocker_buyer_account_id=? AND blocked_buyer_account_id=?) LIMIT 1`).bind(a,b,b,a).first();return!!row}
async function needForOwner(env,buyerId,id){return env.DB.prepare(`SELECT * FROM world_needs WHERE buyer_account_id=? AND public_id=?`).bind(buyerId,id).first()}

async function productTrust(env,thing,listing=null){
  const [evidence,documents,services,transfers]=await Promise.all([
    env.DB.prepare(`SELECT evidence_type,source_type,field_name,provenance,verification_status,receipt_id FROM world_evidence WHERE buyer_account_id=? AND thing_passport_id=?`).bind(thing.buyer_account_id,thing.id).all(),
    env.DB.prepare(`SELECT COUNT(*) count FROM world_relationships r JOIN world_documents d ON d.public_id=CASE WHEN r.from_type='document' THEN r.from_public_id ELSE r.to_public_id END AND d.buyer_account_id=r.buyer_account_id AND d.archived_at IS NULL WHERE r.buyer_account_id=? AND ((r.from_type='thing' AND r.from_public_id=?) OR (r.to_type='thing' AND r.to_public_id=?)) AND (r.from_type='document' OR r.to_type='document')`).bind(thing.buyer_account_id,thing.public_id,thing.public_id).first().catch(()=>({count:0})),
    env.DB.prepare(`SELECT COUNT(*) count FROM passport_service_events WHERE passport_id=? AND is_public=1`).bind(thing.id).first().catch(()=>({count:0})),
    env.DB.prepare(`SELECT COUNT(*) count FROM market_transfers WHERE thing_passport_id=? AND status='COMPLETED'`).bind(thing.id).first()
  ]);
  const rows=evidence.results||[],receiptSupported=rows.some(x=>x.receipt_id||/receipt/i.test(x.source_type||''));
  const identityFields=['manufacturer','model','gtin'].filter(field=>thing[field]||thing[field==='manufacturer'?'manufacturer':field]);
  const verifiedIdentity=rows.filter(x=>identityFields.includes(x.field_name)&&x.verification_status==='VERIFIED').map(x=>x.field_name);
  return {components:{ownership:{state:receiptSupported?'RECEIPT_SUPPORTED':'OWNER_RECORDED',label:receiptSupported?'Receipt-supported ownership':'Owner-recorded ownership'},identity:{state:verifiedIdentity.length?'EVIDENCE_VERIFIED':identityFields.length?'RECORDED':'LIMITED',label:verifiedIdentity.length?`Verified evidence: ${verifiedIdentity.join(', ')}`:identityFields.length?'Identity fields recorded':'Limited identity data'},condition:{state:listing?.condition_grade?'SELLER_CONFIRMED':'NOT_RECORDED',label:listing?.condition_grade?`Seller confirmed · ${listing.condition_grade.replaceAll('_',' ')}`:'Condition not recorded',assessment:'No professional inspection or AI visual assessment is claimed.'},serviceHistory:{state:Number(services?.count||0)>0?'PUBLIC_RECORDS':'NO_VERIFIED_RECORDS',count:Number(services?.count||0),label:Number(services?.count||0)>0?`${services.count} public service record(s)`:'No public verified service records'},documents:{state:Number(documents?.count||0)>0?'PRIVATE_RECORDS_EXIST':'NONE_RECORDED',count:Number(documents?.count||0),label:Number(documents?.count||0)>0?'Supporting documents recorded; private files are not public':'No supporting documents recorded'},ownershipHistory:{state:Number(transfers?.count||0)>0?'TRANSFER_HISTORY':'FIRST_RECORDED_OWNER',count:Number(transfers?.count||0),label:Number(transfers?.count||0)>0?'Previous ownership transfer recorded':'No prior Still transfer recorded'}},score:null};
}

async function sellerTrust(env,sellerId){const account=await env.DB.prepare(`SELECT email_verified,created_at FROM buyer_accounts WHERE id=?`).bind(sellerId).first();const transfers=await env.DB.prepare(`SELECT COUNT(*) count FROM market_transfers WHERE from_buyer_account_id=? AND status='COMPLETED'`).bind(sellerId).first();return{identity:{state:account?.email_verified?'EMAIL_VERIFIED':'ACCOUNT_ONLY',label:account?.email_verified?'Email identity verified':'Still account'},accountSince:account?.created_at?.slice(0,4)||null,completedTransfers:Number(transfers?.count||0),ratings:null,responseReliability:null}}
function conditionJson(row){return{grade:row.condition_grade||null,knownDefects:row.known_defects||null,functionalIssues:row.functional_issues||null,cosmeticIssues:row.cosmetic_issues||null,includedAccessories:safeJson(row.included_accessories_json,[]),sellerConfirmed:Boolean(row.condition_grade),aiAssessment:null,professionalInspection:false}}
function listingSummary(row){return{publicId:row.public_id,status:row.status,thing:{publicId:row.thing_public_id,title:row.thing_title,category:row.category||row.thing_category||null,manufacturer:row.manufacturer||null,model:row.model||null},askingPriceCents:row.asking_price_cents,currency:row.currency,conditionGrade:row.condition_grade||null,coarseLocation:row.coarse_location||null,shippingAvailable:!!row.shipping_available,pickupAvailable:!!row.pickup_available,trustSignals:{receiptSupported:Number(row.receipt_evidence_count||0)>0,serialRecorded:!!row.serial_number,identityRecorded:!!(row.manufacturer||row.model||row.gtin),conditionSellerConfirmed:!!row.condition_grade},publishedAt:row.published_at,updatedAt:row.updated_at}}
const LISTING_SELECT=`SELECT l.*,p.public_id thing_public_id,p.title thing_title,p.purchased_on,p.warranty_until,p.notes private_thing_notes,tp.category thing_category,tp.manufacturer,tp.model,tp.serial_number,tp.gtin,tp.lifecycle_state,tp.review_status,(SELECT COUNT(*) FROM world_evidence e WHERE e.buyer_account_id=l.seller_buyer_account_id AND e.thing_passport_id=l.thing_passport_id AND (e.receipt_id IS NOT NULL OR lower(e.source_type) LIKE '%receipt%')) receipt_evidence_count FROM market_listings l JOIN ownership_passports p ON p.id=l.thing_passport_id LEFT JOIN world_thing_profiles tp ON tp.passport_id=p.id`;
async function listingById(env,id){return env.DB.prepare(`${LISTING_SELECT} WHERE l.public_id=?`).bind(id).first()}
async function listingDetail(env,row,viewerId){const thing=await thingByInternal(env,row.thing_passport_id);const owner=viewerId===row.seller_buyer_account_id;return{...listingSummary(row),description:row.description||null,condition:conditionJson(row),delivery:{paymentMode:'EXTERNAL_MANUAL',paymentNotice:'Payment happens outside Still. Still does not hold money or provide escrow.',locationMode:row.location_mode,coarseLocation:row.coarse_location||null,shippingAvailable:!!row.shipping_available,pickupAvailable:!!row.pickup_available,shippingNotice:row.shipping_available?'Shipping is arranged externally. No tracking provider is connected.':null},productTrust:await productTrust(env,thing,row),sellerTrust:await sellerTrust(env,row.seller_buyer_account_id),marketPassport:{purchasedYear:row.purchased_on?.slice(0,4)||null,warrantyUntil:row.warranty_until||null,serial:{recorded:!!row.serial_number,publicValue:null},privateReceiptImageExposed:false,privateNotesExposed:false},viewer:{isSeller:owner,canOffer:!owner&&row.status==='ACTIVE'},privateSellerNotes:owner?row.seller_notes||null:null}}

function listingInput(body,current={}){return{price:Object.prototype.hasOwnProperty.call(body,'askingPriceCents')?cents(body.askingPriceCents):current.asking_price_cents??null,currency:currency(body.currency||current.currency),description:clean(Object.prototype.hasOwnProperty.call(body,'description')?body.description:current.description,3000)||null,condition:CONDITION_GRADES.has(clean(body.conditionGrade||current.condition_grade,30).toUpperCase())?clean(body.conditionGrade||current.condition_grade,30).toUpperCase():null,knownDefects:clean(Object.prototype.hasOwnProperty.call(body,'knownDefects')?body.knownDefects:current.known_defects,2000)||null,functionalIssues:clean(Object.prototype.hasOwnProperty.call(body,'functionalIssues')?body.functionalIssues:current.functional_issues,2000)||null,cosmeticIssues:clean(Object.prototype.hasOwnProperty.call(body,'cosmeticIssues')?body.cosmeticIssues:current.cosmetic_issues,2000)||null,accessories:Array.isArray(body.includedAccessories)?list(body.includedAccessories):safeJson(current.included_accessories_json,[]),sellerNotes:clean(Object.prototype.hasOwnProperty.call(body,'sellerNotes')?body.sellerNotes:current.seller_notes,2000)||null,category:category(body.category||current.category),coarseLocation:clean(Object.prototype.hasOwnProperty.call(body,'coarseLocation')?body.coarseLocation:current.coarse_location,120)||null,shipping:bool(Object.prototype.hasOwnProperty.call(body,'shippingAvailable')?body.shippingAvailable:current.shipping_available),pickup:Object.prototype.hasOwnProperty.call(body,'pickupAvailable')?bool(body.pickupAvailable):current.pickup_available===undefined?true:!!current.pickup_available}}
async function listingReadiness(env,row){const thing=await thingByInternal(env,row.thing_passport_id),trust=await productTrust(env,thing,row);return{identity:{ready:!!(thing.title&&(thing.model||thing.manufacturer||thing.gtin)),known:{title:thing.title,manufacturer:thing.manufacturer||null,model:thing.model||null,category:row.category||thing.category||null}},receiptEvidence:{ready:trust.components.ownership.state==='RECEIPT_SUPPORTED',label:trust.components.ownership.label},condition:{ready:!!row.condition_grade},price:{ready:Number.isInteger(row.asking_price_cents)&&row.asking_price_cents>0},delivery:{ready:!!(row.shipping_available||row.pickup_available)},identityConflict:thing.review_status==='NEEDS_REVIEW',missing:[...(!row.condition_grade?['condition']:[]),...(!(row.asking_price_cents>0)?['price']:[]),...(!(row.category&&ALLOWED_CATEGORIES.has(row.category))?['supportedCategory']:[]),...(!(row.shipping_available||row.pickup_available)?['deliveryMode']:[])]}}

async function createListing(request,env,buyer){const body=await request.json().catch(()=>null);if(!body)return json({error:'invalid_json'},400);const thing=await ownerThing(env,buyer.buyer_account_id,clean(body.thingId,40));if(!thing){log('authorization_denied',{buyerId:buyer.buyer_account_id,action:'listing_create'});return json({error:'thing_not_owned'},403)}if(thing.kind!=='product'||(thing.lifecycle_state&&thing.lifecycle_state!=='OWNED'))return json({error:'thing_not_market_eligible'},409);if(!thing.lifecycle_state){const profileTs=now();await env.DB.prepare(`INSERT INTO world_thing_profiles(passport_id,buyer_account_id,thing_type,lifecycle_state,source,review_status,created_at,updated_at) VALUES(?,?,?,'OWNED','legacy_market_backfill','CONFIRMED',?,?) ON CONFLICT(passport_id) DO NOTHING`).bind(thing.id,buyer.buyer_account_id,thing.kind||'product',profileTs,profileTs).run();thing.lifecycle_state='OWNED';thing.thing_type=thing.kind||'product'}const existing=await env.DB.prepare(`SELECT public_id,status FROM market_listings WHERE thing_passport_id=? AND status IN ('DRAFT','ACTIVE','RESERVED','TRANSFER_PENDING')`).bind(thing.id).first();if(existing)return json({error:'active_listing_exists',listingId:existing.public_id,status:existing.status},409);const input=listingInput(body,{category:thing.category}),needId=clean(body.needId,40);let need=null;if(needId){need=await needForOwner(env,buyer.buyer_account_id,needId);if(!need||need.need_type!=='SELL')return json({error:'sell_need_not_found'},404)}const ts=now(),id=uid('mli_'),pid=publicId('LST');await env.DB.batch([env.DB.prepare(`INSERT INTO market_listings(id,public_id,seller_buyer_account_id,thing_passport_id,status,asking_price_cents,currency,description,condition_grade,known_defects,functional_issues,cosmetic_issues,included_accessories_json,seller_notes,category,coarse_location,shipping_available,pickup_available,sell_need_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,pid,buyer.buyer_account_id,thing.id,'DRAFT',input.price,input.currency,input.description,input.condition,input.knownDefects,input.functionalIssues,input.cosmeticIssues,JSON.stringify(input.accessories),input.sellerNotes,input.category,input.coarseLocation,input.shipping?1:0,input.pickup?1:0,need?.id||null,ts,ts),historyStatement(env,buyer.buyer_account_id,'thing',thing.public_id,'market.listing_draft_created','Market listing draft created',{listingId:pid},'market',pid)]);log('listing_created',{buyerId:buyer.buyer_account_id,listingId:pid,thingId:thing.public_id});const row=await listingById(env,pid);return json({ok:true,listing:await listingDetail(env,row,buyer.buyer_account_id),readiness:await listingReadiness(env,row)},201)}
async function updateListing(request,env,buyer,id){const row=await listingById(env,id);if(!row||row.seller_buyer_account_id!==buyer.buyer_account_id)return json({error:'not_found'},404);if(!['DRAFT','ACTIVE'].includes(row.status))return json({error:'listing_not_editable'},409);const body=await request.json().catch(()=>null);if(!body)return json({error:'invalid_json'},400);const input=listingInput(body,row),ts=now();await env.DB.prepare(`UPDATE market_listings SET asking_price_cents=?,currency=?,description=?,condition_grade=?,known_defects=?,functional_issues=?,cosmetic_issues=?,included_accessories_json=?,seller_notes=?,category=?,coarse_location=?,shipping_available=?,pickup_available=?,updated_at=? WHERE id=? AND seller_buyer_account_id=?`).bind(input.price,input.currency,input.description,input.condition,input.knownDefects,input.functionalIssues,input.cosmeticIssues,JSON.stringify(input.accessories),input.sellerNotes,input.category,input.coarseLocation,input.shipping?1:0,input.pickup?1:0,ts,row.id,buyer.buyer_account_id).run();const fresh=await listingById(env,id);if(fresh.status==='ACTIVE')await regenerateMatches(env,{listingId:fresh.id});return json({ok:true,listing:await listingDetail(env,fresh,buyer.buyer_account_id),readiness:await listingReadiness(env,fresh)})}
async function publishListing(env,buyer,id){const row=await listingById(env,id);if(!row||row.seller_buyer_account_id!==buyer.buyer_account_id)return json({error:'not_found'},404);if(row.status!=='DRAFT')return json({error:'invalid_listing_transition'},409);const readiness=await listingReadiness(env,row);if(readiness.identityConflict)return json({error:'identity_review_required',readiness},409);if(readiness.missing.length)return json({error:'listing_not_ready',readiness},422);const ts=now();await env.DB.batch([env.DB.prepare(`UPDATE market_listings SET status='ACTIVE',published_at=?,updated_at=? WHERE id=? AND seller_buyer_account_id=?`).bind(ts,ts,row.id,buyer.buyer_account_id),historyStatement(env,buyer.buyer_account_id,'thing',row.thing_public_id,'market.listing_published','Thing listed in Still Market',{listingId:id,askingPriceCents:row.asking_price_cents,currency:row.currency},'market',id)]);await regenerateMatches(env,{listingId:row.id});log('listing_published',{buyerId:buyer.buyer_account_id,listingId:id});return json({ok:true,listing:await listingDetail(env,await listingById(env,id),buyer.buyer_account_id)})}
async function withdrawListing(env,buyer,id){const row=await listingById(env,id);if(!row||row.seller_buyer_account_id!==buyer.buyer_account_id)return json({error:'not_found'},404);if(!['DRAFT','ACTIVE'].includes(row.status))return json({error:'invalid_listing_transition'},409);const ts=now();await env.DB.batch([env.DB.prepare(`UPDATE market_listings SET status='WITHDRAWN',withdrawn_at=?,updated_at=? WHERE id=?`).bind(ts,ts,row.id),env.DB.prepare(`UPDATE market_offers SET status='EXPIRED',updated_at=? WHERE listing_id=? AND status IN ('PENDING','COUNTERED')`).bind(ts,row.id),historyStatement(env,buyer.buyer_account_id,'thing',row.thing_public_id,'market.listing_withdrawn','Market listing withdrawn',{listingId:id},'market',id)]);log('listing_withdrawn',{buyerId:buyer.buyer_account_id,listingId:id});return json({ok:true,status:'WITHDRAWN'})}

function wantedJson(row){return{publicId:row.public_id,title:row.title,category:row.category||null,manufacturer:row.manufacturer||null,model:row.model||null,requirements:safeJson(row.requirements_json,[]),maxPriceCents:row.max_price_cents,currency:row.currency,minCondition:row.min_condition||null,locationPreference:row.location_preference||null,shippingAllowed:!!row.shipping_allowed,status:row.status,needId:row.need_public_id||null,createdAt:row.created_at,updatedAt:row.updated_at}}
async function wantedById(env,buyerId,id){return env.DB.prepare(`SELECT w.*,n.public_id need_public_id FROM market_wanted w LEFT JOIN world_needs n ON n.id=w.need_id WHERE w.buyer_account_id=? AND w.public_id=?`).bind(buyerId,id).first()}
function wantedInput(body,current={}){const grade=clean(body.minCondition||current.min_condition,30).toUpperCase();return{title:clean(Object.prototype.hasOwnProperty.call(body,'title')?body.title:current.title,180),category:category(body.category||current.category),manufacturer:clean(Object.prototype.hasOwnProperty.call(body,'manufacturer')?body.manufacturer:current.manufacturer,120)||null,model:clean(Object.prototype.hasOwnProperty.call(body,'model')?body.model:current.model,120)||null,requirements:Array.isArray(body.requirements)?list(body.requirements):safeJson(current.requirements_json,[]),maxPrice:Object.prototype.hasOwnProperty.call(body,'maxPriceCents')?cents(body.maxPriceCents):current.max_price_cents??null,currency:currency(body.currency||current.currency),minCondition:CONDITION_GRADES.has(grade)?grade:null,location:clean(Object.prototype.hasOwnProperty.call(body,'locationPreference')?body.locationPreference:current.location_preference,120)||null,shipping:Object.prototype.hasOwnProperty.call(body,'shippingAllowed')?bool(body.shippingAllowed):current.shipping_allowed===undefined?true:!!current.shipping_allowed}}
async function createWantedFromBody(env,buyer,body){
  const input=wantedInput(body);
  if(input.title.length<2)return{response:json({error:'title_required'},422)};
  let need=null;
  const needId=clean(body.needId,40);
  if(needId){
    need=await needForOwner(env,buyer.buyer_account_id,needId);
    if(!need||!['BUY','FIND','REPLACE'].includes(need.need_type))return{response:json({error:'buy_need_not_found'},404)};
    const existing=await env.DB.prepare(`SELECT public_id FROM market_wanted WHERE buyer_account_id=? AND need_id=? AND status IN ('ACTIVE','PAUSED')`).bind(buyer.buyer_account_id,need.id).first();
    if(existing)return{response:json({error:'wanted_for_need_exists',wantedId:existing.public_id},409)};
  }
  const ts=now(),id=uid('mwa_'),pid=publicId('WNT');
  await env.DB.batch([env.DB.prepare(`INSERT INTO market_wanted(id,public_id,buyer_account_id,need_id,title,normalized_title,category,manufacturer,model,requirements_json,max_price_cents,currency,min_condition,location_preference,shipping_allowed,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'ACTIVE',?,?)`).bind(id,pid,buyer.buyer_account_id,need?.id||null,input.title,normalized(input.title),input.category,input.manufacturer,input.model,JSON.stringify(input.requirements),input.maxPrice,input.currency,input.minCondition,input.location,input.shipping?1:0,ts,ts),historyStatement(env,buyer.buyer_account_id,'wanted',pid,'wanted.created','Wanted Object created',{needId:needId||null},'market',pid)]);
  await regenerateMatches(env,{wantedId:id});
  log('wanted_created',{buyerId:buyer.buyer_account_id,wantedId:pid,linkedNeed:Boolean(need)});
  return{wanted:wantedJson(await wantedById(env,buyer.buyer_account_id,pid))};
}

function words(value){return normalized(value).split(' ').filter(x=>x.length>1)}
function deterministicMatch(wanted,listing){const reasons=[],failed=[];let score=20;const lcat=listing.category||listing.thing_category||null;if(wanted.category){if(lcat===wanted.category){reasons.push('Category matches');score+=15}else failed.push('Category does not match')}if(wanted.manufacturer){if(normalized(listing.manufacturer)===normalized(wanted.manufacturer)){reasons.push('Manufacturer matches');score+=15}else failed.push('Manufacturer does not match')}if(wanted.model){if(normalized(`${listing.model||''} ${listing.thing_title||''}`).includes(normalized(wanted.model))){reasons.push('Model matches');score+=25}else failed.push('Model does not match')}else{const wantedWords=words(wanted.title),hay=new Set(words(`${listing.thing_title} ${listing.manufacturer||''} ${listing.model||''}`)),common=wantedWords.filter(x=>hay.has(x));if(common.length){reasons.push('Recorded title terms match');score+=Math.min(20,common.length*7)}else failed.push('No title terms match')}if(wanted.max_price_cents!==null&&wanted.max_price_cents!==undefined){if(listing.asking_price_cents<=wanted.max_price_cents){reasons.push('Within stated budget');score+=15}else failed.push('Above stated budget')}if(wanted.min_condition){if((CONDITION_RANK[listing.condition_grade]??-1)>=CONDITION_RANK[wanted.min_condition]){reasons.push('Condition meets minimum');score+=10}else failed.push('Condition below minimum or unknown')}if(wanted.location_preference&&normalized(wanted.location_preference)!==normalized(listing.coarse_location)){if(listing.shipping_available&&wanted.shipping_allowed)reasons.push('External shipping is available');else failed.push('Location or delivery preference does not match')}if(!wanted.shipping_allowed&&!listing.pickup_available)failed.push('Pickup is unavailable');const hay=normalized(`${listing.thing_title} ${listing.manufacturer||''} ${listing.model||''} ${listing.description||''} ${listing.included_accessories_json||''}`);for(const requirement of safeJson(wanted.requirements_json,[])){if(hay.includes(normalized(requirement))){reasons.push(`Requirement recorded: ${clean(requirement,80)}`);score+=5}else failed.push(`Requirement not recorded: ${clean(requirement,80)}`)}return{valid:failed.length===0,score:Math.min(100,score),reasons,failedConstraints:failed}}
async function regenerateMatches(env,{wantedId=null,listingId=null}={}){const wants=await env.DB.prepare(`SELECT * FROM market_wanted WHERE status='ACTIVE' ${wantedId?'AND id=?':''}`).bind(...(wantedId?[wantedId]:[])).all(),listings=await env.DB.prepare(`${LISTING_SELECT} WHERE l.status='ACTIVE' ${listingId?'AND l.id=?':''}`).bind(...(listingId?[listingId]:[])).all();for(const wanted of wants.results||[])for(const listing of listings.results||[]){if(wanted.buyer_account_id===listing.seller_buyer_account_id||await blockExists(env,wanted.buyer_account_id,listing.seller_buyer_account_id))continue;const match=deterministicMatch(wanted,listing),ts=now();if(!match.valid){await env.DB.prepare(`DELETE FROM market_matches WHERE wanted_id=? AND listing_id=?`).bind(wanted.id,listing.id).run();continue}await env.DB.prepare(`INSERT INTO market_matches(id,public_id,wanted_id,listing_id,score,reasons_json,failed_constraints_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?, ?,?) ON CONFLICT(wanted_id,listing_id) DO UPDATE SET score=excluded.score,reasons_json=excluded.reasons_json,failed_constraints_json=excluded.failed_constraints_json,updated_at=excluded.updated_at`).bind(uid('mma_'),publicId('MAT'),wanted.id,listing.id,match.score,JSON.stringify(match.reasons),JSON.stringify(match.failedConstraints),ts,ts).run();await notificationStatement(env,wanted.buyer_account_id,`wanted-match:${wanted.id}:${listing.id}`,'WANTED_MATCH','A real listing matches your Want',wanted.title,`/app/market/listing/${listing.public_id}`).run();log('match_generated',{wantedId:wanted.public_id,listingId:listing.public_id,score:match.score})}}
async function matchesForWanted(env,wanted){const rows=await env.DB.prepare(`SELECT m.*,l.public_id listing_public_id,l.thing_passport_id,l.asking_price_cents,l.currency,l.condition_grade,l.coarse_location,l.shipping_available,l.pickup_available,l.category,l.published_at,l.updated_at,p.public_id thing_public_id,p.title thing_title,tp.category thing_category,tp.manufacturer,tp.model,tp.serial_number,tp.gtin FROM market_matches m JOIN market_listings l ON l.id=m.listing_id JOIN ownership_passports p ON p.id=l.thing_passport_id LEFT JOIN world_thing_profiles tp ON tp.passport_id=p.id WHERE m.wanted_id=? AND l.status='ACTIVE' ORDER BY m.score DESC LIMIT 100`).bind(wanted.id).all();return(rows.results||[]).map(row=>({publicId:row.public_id,score:row.score,reasons:safeJson(row.reasons_json,[]),failedConstraints:safeJson(row.failed_constraints_json,[]),listing:listingSummary({...row,public_id:row.listing_public_id})}))}

async function reverseMatches(env,buyer,thing){const pref=await env.DB.prepare(`SELECT * FROM market_thing_preferences WHERE buyer_account_id=? AND thing_passport_id=?`).bind(buyer.buyer_account_id,thing.id).first();if(!pref?.private_matching_enabled)return{enabled:false,count:0,matches:[]};const wants=await env.DB.prepare(`SELECT * FROM market_wanted WHERE status='ACTIVE' AND buyer_account_id<>? ORDER BY updated_at DESC LIMIT 300`).bind(buyer.buyer_account_id).all(),pseudo={thing_title:thing.title,thing_category:thing.category,category:thing.category,manufacturer:thing.manufacturer,model:thing.model,asking_price_cents:pref.consider_price_cents,condition_grade:null,coarse_location:null,shipping_available:0,pickup_available:1,description:'',included_accessories_json:'[]'},matches=[];for(const wanted of wants.results||[]){if(await blockExists(env,buyer.buyer_account_id,wanted.buyer_account_id))continue;const copy={...wanted,max_price_cents:pref.consider_price_cents===null?null:wanted.max_price_cents,min_condition:null,location_preference:null},match=deterministicMatch(copy,pseudo);if(match.valid)matches.push({wantedId:wanted.public_id,title:wanted.title,score:match.score,reasons:match.reasons,priceFit:pref.consider_price_cents===null?'UNKNOWN':'PRIVATE_PRICE_COMPARED'})}if(matches.length)log('reverse_match',{buyerId:buyer.buyer_account_id,thingId:thing.public_id,count:matches.length});return{enabled:true,count:matches.length,matches:matches.slice(0,20),buyerIdentitiesExposed:false,thingPublished:false,considerPriceCents:pref.consider_price_cents,currency:pref.currency}}

async function searchListings(env,buyer,url){const q=normalized(url.searchParams.get('q')),cat=category(url.searchParams.get('category')),min=cents(url.searchParams.get('minPrice')),max=cents(url.searchParams.get('maxPrice')),grade=clean(url.searchParams.get('condition'),30).toUpperCase(),location=clean(url.searchParams.get('location'),120),shipping=url.searchParams.get('shipping')==='1',trust=clean(url.searchParams.get('trust'),30).toLowerCase(),limit=Math.min(50,Math.max(1,Number(url.searchParams.get('limit'))||24)),offset=Math.max(0,Number(url.searchParams.get('offset'))||0);let sql=`${LISTING_SELECT} WHERE l.status='ACTIVE' AND l.seller_buyer_account_id<>? AND NOT EXISTS(SELECT 1 FROM market_blocks b WHERE (b.blocker_buyer_account_id=? AND b.blocked_buyer_account_id=l.seller_buyer_account_id) OR (b.blocker_buyer_account_id=l.seller_buyer_account_id AND b.blocked_buyer_account_id=?))`,args=[buyer.buyer_account_id,buyer.buyer_account_id,buyer.buyer_account_id];for(const term of words(q)){sql+=` AND lower(p.title||' '||COALESCE(tp.manufacturer,'')||' '||COALESCE(tp.model,'')) LIKE ?`;args.push(`%${term}%`)}if(cat){sql+=` AND COALESCE(l.category,tp.category)=?`;args.push(cat)}if(min!==null){sql+=` AND l.asking_price_cents>=?`;args.push(min)}if(max!==null){sql+=` AND l.asking_price_cents<=?`;args.push(max)}if(CONDITION_GRADES.has(grade)){const acceptable=Object.entries(CONDITION_RANK).filter(([,rank])=>rank>=CONDITION_RANK[grade]).map(([key])=>key);sql+=` AND l.condition_grade IN (${acceptable.map(()=>'?').join(',')})`;args.push(...acceptable)}if(location){sql+=` AND (lower(l.coarse_location)=lower(?) OR l.shipping_available=1)`;args.push(location)}if(shipping)sql+=` AND l.shipping_available=1`;if(trust==='receipt_supported')sql+=` AND EXISTS(SELECT 1 FROM world_evidence te WHERE te.buyer_account_id=l.seller_buyer_account_id AND te.thing_passport_id=l.thing_passport_id AND (te.receipt_id IS NOT NULL OR lower(te.source_type) LIKE '%receipt%'))`;else if(trust==='identity_recorded')sql+=` AND (tp.manufacturer IS NOT NULL OR tp.model IS NOT NULL OR tp.gtin IS NOT NULL)`;else if(trust==='condition_recorded')sql+=` AND l.condition_grade IS NOT NULL`;sql+=` ORDER BY receipt_evidence_count DESC,(tp.manufacturer IS NOT NULL OR tp.model IS NOT NULL OR tp.gtin IS NOT NULL) DESC,(l.condition_grade IS NOT NULL) DESC,l.published_at DESC,l.public_id LIMIT ? OFFSET ?`;args.push(limit+1,offset);const rows=await env.DB.prepare(sql).bind(...args).all(),items=(rows.results||[]).slice(0,limit).map(listingSummary);return json({listings:items,pagination:{limit,offset,nextOffset:(rows.results||[]).length>limit?offset+limit:null},filters:{query:q||null,category:cat,minPriceCents:min,maxPriceCents:max,condition:CONDITION_GRADES.has(grade)?grade:null,location:location||null,shipping,trust:['receipt_supported','identity_recorded','condition_recorded'].includes(trust)?trust:null}})}

async function createOffer(request,env,buyer){const body=await request.json().catch(()=>null);if(!body)return json({error:'invalid_json'},400);const listing=await listingById(env,clean(body.listingId,40));if(!listing||listing.status!=='ACTIVE'||await blockExists(env,buyer.buyer_account_id,listing?.seller_buyer_account_id))return json({error:'listing_not_available'},404);if(listing.seller_buyer_account_id===buyer.buyer_account_id)return json({error:'seller_cannot_offer'},409);const amount=cents(body.amountCents);if(amount===null||amount<1)return json({error:'valid_amount_required'},422);if(currency(body.currency)!==listing.currency)return json({error:'currency_mismatch'},422);const existing=await env.DB.prepare(`SELECT public_id FROM market_offers WHERE listing_id=? AND buyer_account_id=? AND status IN ('PENDING','COUNTERED','ACCEPTED')`).bind(listing.id,buyer.buyer_account_id).first();if(existing)return json({error:'open_offer_exists',offerId:existing.public_id},409);const ts=now(),id=uid('mof_'),pid=publicId('OFR');await env.DB.batch([env.DB.prepare(`INSERT INTO market_offers(id,public_id,listing_id,buyer_account_id,current_amount_cents,currency,status,message,expires_at,created_at,updated_at) VALUES(?,?,?,?,?,?,'PENDING',?,?,?,?)`).bind(id,pid,listing.id,buyer.buyer_account_id,amount,listing.currency,clean(body.message,1000)||null,safeDate(body.expiresAt),ts,ts),env.DB.prepare(`INSERT INTO market_offer_events(id,public_id,offer_id,actor_buyer_account_id,event_type,amount_cents,message,created_at) VALUES(?,?,?,?,?,?,?,?)`).bind(uid('moe_'),publicId('OEV'),id,buyer.buyer_account_id,'CREATED',amount,clean(body.message,1000)||null,ts),notificationStatement(env,listing.seller_buyer_account_id,`offer:${id}:created`,'OFFER_RECEIVED','Offer received',listing.thing_title,`/app/market/listing/${listing.public_id}`)]);log('offer_created',{buyerId:buyer.buyer_account_id,offerId:pid,listingId:listing.public_id,amountCents:amount,currency:listing.currency});return json({ok:true,offer:await offerDetail(env,pid,buyer.buyer_account_id)},201)}
async function offerRow(env,id){return env.DB.prepare(`SELECT o.*,l.public_id listing_public_id,l.seller_buyer_account_id,l.thing_passport_id,l.status listing_status,l.pickup_available,l.shipping_available,p.title thing_title FROM market_offers o JOIN market_listings l ON l.id=o.listing_id JOIN ownership_passports p ON p.id=l.thing_passport_id WHERE o.public_id=?`).bind(id).first()}
