async function createDeal(env,row){const existing=await env.DB.prepare(`SELECT public_id FROM market_deals WHERE accepted_offer_id=?`).bind(row.id).first();if(existing)return existing.public_id;const ts=now(),id=uid('mdl_'),pid=publicId('DEL'),delivery=row.pickup_available?'PICKUP':'SHIPPING_EXTERNAL';await env.DB.batch([env.DB.prepare(`INSERT INTO market_deals(id,public_id,listing_id,accepted_offer_id,seller_buyer_account_id,buyer_buyer_account_id,agreed_amount_cents,currency,status,payment_mode,delivery_mode,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,'EXTERNAL_MANUAL',?,?,?)`).bind(id,pid,row.listing_id,row.id,row.seller_buyer_account_id,row.buyer_account_id,row.current_amount_cents,row.currency,'AGREED',delivery,ts,ts),env.DB.prepare(`UPDATE market_offers SET status=CASE WHEN id=? THEN 'ACCEPTED' ELSE 'DECLINED' END,updated_at=? WHERE listing_id=? AND status IN ('PENDING','COUNTERED')`).bind(row.id,ts,row.listing_id),env.DB.prepare(`UPDATE market_listings SET status='RESERVED',reserved_at=?,updated_at=? WHERE id=? AND status='ACTIVE'`).bind(ts,ts,row.listing_id),notificationStatement(env,row.buyer_account_id,`deal:${id}:created`,'OFFER_ACCEPTED','Offer accepted','Review the manual payment and handoff steps.',`/app/market/deal/${pid}`),notificationStatement(env,row.seller_buyer_account_id,`deal:${id}:created`,'DEAL_CREATED','Deal created','Payment and handoff remain external/manual.',`/app/market/deal/${pid}`)]);log('deal_created',{dealId:pid,listingId:row.listing_public_id,paymentMode:'EXTERNAL_MANUAL',deliveryMode:delivery});return pid}
async function updateOffer(request,env,buyer,id){const row=await offerRow(env,id);if(!row||![row.buyer_account_id,row.seller_buyer_account_id].includes(buyer.buyer_account_id))return json({error:'not_found'},404);const body=await request.json().catch(()=>({})),action=clean(body.action,30).toUpperCase(),seller=buyer.buyer_account_id===row.seller_buyer_account_id,ts=now();let status=row.status,event=action,amount=row.current_amount_cents;if(action==='WITHDRAW'&&!seller&&['PENDING','COUNTERED'].includes(row.status))status='WITHDRAWN';else if(action==='DECLINE'&&seller&&['PENDING','COUNTERED'].includes(row.status))status='DECLINED';else if(action==='COUNTER'&&seller&&row.status==='PENDING'){amount=cents(body.amountCents);if(amount===null||amount<1)return json({error:'valid_amount_required'},422);status='COUNTERED'}else if(action==='ACCEPT'&&seller&&row.status==='PENDING')status='ACCEPTED';else if(action==='ACCEPT_COUNTER'&&!seller&&row.status==='COUNTERED')status='ACCEPTED';else return json({error:'invalid_offer_transition'},409);await env.DB.batch([env.DB.prepare(`UPDATE market_offers SET status=?,current_amount_cents=?,updated_at=? WHERE id=? AND status=?`).bind(status,amount,ts,row.id,row.status),env.DB.prepare(`INSERT INTO market_offer_events(id,public_id,offer_id,actor_buyer_account_id,event_type,amount_cents,message,created_at) VALUES(?,?,?,?,?,?,?,?)`).bind(uid('moe_'),publicId('OEV'),row.id,buyer.buyer_account_id,event,amount,clean(body.message,1000)||null,ts),notificationStatement(env,seller?row.buyer_account_id:row.seller_buyer_account_id,`offer:${row.id}:${ts}`,'OFFER_UPDATED',status==='COUNTERED'?'Counteroffer received':`Offer ${status.toLocaleLowerCase()}`,row.thing_title,`/app/market/listing/${row.listing_public_id}`)]);let dealId=null;if(status==='ACCEPTED')dealId=await createDeal(env,{...row,current_amount_cents:amount});log('offer_state_changed',{offerId:id,from:row.status,to:status,actorRole:seller?'SELLER':'BUYER'});return json({ok:true,offer:await offerDetail(env,id,buyer.buyer_account_id),dealId})}

